mapper.select:
SELECT id, user_id, title, content, word_count, chapter_count, encoding, create_time
FROM reader_file
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM reader_file
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE reader_file
SET title = #{title}
WHERE id = #{id}
  AND user_id = #{userId}
